import {
  ActivityIndicator,
  Image,
  Pressable,
  StyleSheet,
  Text,
  View,
} from "react-native";

import { useHealth } from "../api/useHealth";
import { useThemeColors } from "../theme/useThemeColors";

// Tela provisória do passo 1: prova que a web fala com a API. Sai quando chegar o login.
export function ApiStatusScreen() {
  const colors = useThemeColors();
  const health = useHealth();

  return (
    <View style={styles.container}>
      <Image
        source={require("../../../../design/assets/maxx-ouro.png")}
        style={styles.logo}
        resizeMode="contain"
        accessibilityLabel="Maxx"
      />

      <View testID="estado-api" style={styles.status}>
        {health.isPending && (
          <>
            <ActivityIndicator color={colors.ink2} />
            <Text style={[styles.message, { color: colors.ink2 }]}>
              Conectando...
            </Text>
          </>
        )}

        {health.isSuccess && (
          <>
            <Text style={[styles.message, { color: colors.ink }]}>
              Tudo certo por aqui.
            </Text>
            <Text style={[styles.detail, { color: colors.ink2 }]}>
              A API respondeu {health.data.httpStatus}.
            </Text>
          </>
        )}

        {health.isError && (
          <>
            <Text style={[styles.message, { color: colors.ink }]}>
              Não conseguimos falar com o servidor agora.
            </Text>
            <Pressable
              accessibilityRole="button"
              onPress={() => health.refetch()}
              style={[styles.button, { backgroundColor: colors.surface }]}
            >
              <Text style={[styles.buttonText, { color: colors.ink }]}>
                Tentar de novo
              </Text>
            </Pressable>
          </>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
    paddingHorizontal: 16,
    gap: 24,
  },
  logo: { width: 106, height: 28 },
  status: { alignItems: "center", gap: 8 },
  message: { fontSize: 14, lineHeight: 20, textAlign: "center" },
  detail: { fontSize: 12, lineHeight: 16, textAlign: "center" },
  // Botão discreto da identidade: 32 de altura visual, raio 8, texto 13, 44 de toque.
  button: {
    height: 32,
    borderRadius: 8,
    paddingHorizontal: 12,
    justifyContent: "center",
    marginTop: 8,
  },
  buttonText: { fontSize: 13, fontWeight: "600" },
});
import type { ApiClient } from "@maxx/api-client";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { fireEvent, render, screen } from "@testing-library/react-native";

import { ApiClientProvider } from "../api/ApiClientProvider";
import { ApiStatusScreen } from "./ApiStatusScreen";

function renderWith(get: jest.Mock) {
  const client = { GET: get } as unknown as ApiClient;
  // gcTime infinito: sem o timer de coleta, o Jest termina sem processo pendurado.
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false, gcTime: Infinity } },
  });
  return render(
    <QueryClientProvider client={queryClient}>
      <ApiClientProvider client={client}>
        <ApiStatusScreen />
      </ApiClientProvider>
    </QueryClientProvider>,
  );
}

const ok = { data: { status: "ok" }, response: { ok: true, status: 200 } };
const unavailable = { data: undefined, response: { ok: false, status: 503 } };

test("mostra que a API respondeu 200", async () => {
  const get = jest.fn().mockResolvedValue(ok);
  await renderWith(get);

  expect(await screen.findByText("A API respondeu 200.")).toBeTruthy();
  expect(get).toHaveBeenCalledWith("/api/health");
});

test("com a API fora, mostra mensagem amigável e deixa tentar de novo", async () => {
  const get = jest
    .fn()
    .mockResolvedValueOnce(unavailable)
    .mockResolvedValueOnce(ok);
  await renderWith(get);

  expect(
    await screen.findByText("Não conseguimos falar com o servidor agora."),
  ).toBeTruthy();

  fireEvent.press(screen.getByRole("button", { name: "Tentar de novo" }));

  expect(await screen.findByText("A API respondeu 200.")).toBeTruthy();
  expect(get).toHaveBeenCalledTimes(2);
});

test("sem rede, a mensagem também é amigável", async () => {
  const get = jest.fn().mockRejectedValue(new TypeError("Failed to fetch"));
  await renderWith(get);

  expect(
    await screen.findByText("Não conseguimos falar com o servidor agora."),
  ).toBeTruthy();
  expect(screen.queryByText(/Failed to fetch/)).toBeNull();
});
import { render, screen } from "@testing-library/react-native";
import { Platform, StyleSheet, Text } from "react-native";

import { PhoneFrame } from "./PhoneFrame";

// O `react-native` exporta o hook por getter, então o mock vai no módulo de origem.
const mockWindow = { width: 0, height: 0 };
jest.mock("react-native/Libraries/Utilities/useWindowDimensions", () => ({
  __esModule: true,
  default: () => ({ ...mockWindow, scale: 1, fontScale: 1 }),
}));

function renderAt(os: typeof Platform.OS, width: number, height: number) {
  jest.replaceProperty(Platform, "OS", os);
  Object.assign(mockWindow, { width, height });
  return render(
    <PhoneFrame>
      <Text>conteúdo</Text>
    </PhoneFrame>,
  );
}

afterEach(() => jest.restoreAllMocks());

test("na web a partir de 600 px, mostra a coluna de 390 px com teto de 844 px", async () => {
  await renderAt("web", 1280, 1000);

  const frame = StyleSheet.flatten(screen.getByTestId("moldura").props.style);
  expect(frame.width).toBe(390);
  expect(frame.height).toBe(844);
  expect(frame.borderWidth).toBe(1);
  expect(screen.getByText("conteúdo")).toBeTruthy();
});

test("com a janela mais baixa que 844 px, a moldura acompanha a altura da janela", async () => {
  await renderAt("web", 1280, 700);

  expect(
    StyleSheet.flatten(screen.getByTestId("moldura").props.style).height,
  ).toBe(700);
});

test("na web abaixo de 600 px, o app ocupa a largura toda, sem moldura", async () => {
  await renderAt("web", 599, 900);

  expect(screen.queryByTestId("moldura")).toBeNull();
  expect(screen.getByText("conteúdo")).toBeTruthy();
});

test("no nativo nunca há moldura, mesmo em tela larga", async () => {
  await renderAt("ios", 1024, 1366);

  expect(screen.queryByTestId("moldura")).toBeNull();
});
