import json from "../../../../design/tokens.json";

// Camada tipada sobre design/tokens.json, a fonte dos valores. Cores e tiers vêm direto do
// JSON. Tamanhos, raios e tipografia estão lá em texto livre ("28/32, Archivo 800"), então
// viram números aqui; tokens.test.ts confere cada um contra o texto do JSON.

export type ThemeName = "claro" | "escuro";
export type ThemeColors = typeof json.cores.claro;

export const cores: Record<ThemeName, ThemeColors> = {
  claro: json.cores.claro,
  escuro: json.cores.escuro,
};

export type Tier = "bronze" | "prata" | "ouro" | "diamante";
export type Raridade = "comum" | "raro" | "epico" | "lendario";

export interface TierStyle {
  pontos: string;
  medalhao: [string, string, string];
  borda: string;
  glifo: string;
  pill: [string, string, string, string, string];
  pillTexto: string;
  texto: Record<ThemeName, string>;
  fundoGrade: Record<ThemeName, [string, string]>;
}

export const tiers = {
  bronze: json.tiers.bronze,
  prata: json.tiers.prata,
  ouro: json.tiers.ouro,
  diamante: json.tiers.diamante,
} as Record<Tier, TierStyle>;

export const espacamento = {
  base: 4,
  escala: [4, 8, 12, 16, 24, 32],
  margemLateral: 16,
  respiroAntesDaNavegacao: 24,
} as const;

export const raios = {
  filtros: 8,
  campos: 8,
  botoes: 8,
  controleSegmentado: 10,
  // Segmento ativo dentro do trilho (identidade-visual.md); o JSON só traz o raio do trilho.
  segmentoAtivo: 8,
  cardMenor: 12,
  cardMaior: 16,
  realceNav: 14,
  pill: 999,
} as const;

export const tamanhos = {
  alvoDeToque: 44,
  botaoDiscreto: { altura: 32, texto: 13, toque: 44 },
  botaoGrande: 50,
  campo: 48,
  navegacaoInferior: 84,
  iconeNav: 26,
  realceAbaAtiva: 44,
  avatarNav: 30,
  avatarPost: 36,
  medalhaoLista: 48,
  bolinhaNovidade: { diametro: 8, halo: 2 },
  fotoPost: 390,
  tracoIcone: 1.8,
} as const;

export interface EstiloDeTexto {
  familia: "Archivo" | "Instrument Sans";
  tamanho: number;
  // A escala não define altura de linha para os pontos.
  alturaLinha?: number;
  peso: 400 | 500 | 600 | 700 | 800;
  italico?: boolean;
  caixaAlta?: boolean;
  // Em em, como no JSON.
  espacamentoLetras?: number;
}

export const tipografia = {
  display: { familia: "Archivo", tamanho: 28, alturaLinha: 32, peso: 800 },
  titulo: { familia: "Archivo", tamanho: 22, alturaLinha: 26, peso: 700 },
  pontos: { familia: "Archivo", tamanho: 18, peso: 800, italico: true },
  secao: { familia: "Archivo", tamanho: 15, alturaLinha: 19, peso: 700 },
  corpo: {
    familia: "Instrument Sans",
    tamanho: 14,
    alturaLinha: 20,
    peso: 400,
  },
  legenda: {
    familia: "Instrument Sans",
    tamanho: 12,
    alturaLinha: 16,
    peso: 500,
  },
  rotulo: {
    familia: "Instrument Sans",
    tamanho: 11,
    alturaLinha: 14,
    peso: 600,
    caixaAlta: true,
    espacamentoLetras: 0.04,
  },
} as const satisfies Record<string, EstiloDeTexto>;

import json from "../../../../design/tokens.json";
import {
  cores,
  espacamento,
  raios,
  tamanhos,
  tiers,
  tipografia,
  type EstiloDeTexto,
  type Tier,
} from "./tokens";

const TIERS: Tier[] = ["bronze", "prata", "ouro", "diamante"];

// Primeiro grupo numérico do texto que casa com a expressão.
function numero(texto: string, expressao: RegExp): number {
  const achado = expressao.exec(texto);
  if (!achado?.[1]) throw new Error(`"${texto}" não casa com ${expressao}`);
  return Number(achado[1]);
}

test("as cores são as do JSON, com as mesmas chaves nos dois temas", () => {
  expect(cores.claro).toEqual(json.cores.claro);
  expect(cores.escuro).toEqual(json.cores.escuro);
  expect(Object.keys(cores.escuro).sort()).toEqual(
    Object.keys(cores.claro).sort(),
  );
});

test.each(TIERS)("o tier %s tem os gradientes no formato declarado", (tier) => {
  const estilo = tiers[tier];
  expect(estilo).toEqual(json.tiers[tier]);
  expect(estilo.medalhao).toHaveLength(3);
  expect(estilo.pill).toHaveLength(5);
  expect(estilo.fundoGrade.claro).toHaveLength(2);
  expect(estilo.fundoGrade.escuro).toHaveLength(2);
});

test("o espaçamento é o do JSON e cai na grade de 4 px", () => {
  expect(espacamento).toEqual(json.espacamento);
  for (const valor of espacamento.escala) {
    expect(valor % espacamento.base).toBe(0);
  }
});

test("os raios conferem com o JSON", () => {
  const texto = json.raios;
  expect(raios.filtros).toBe(texto.filtros);
  expect(raios.campos).toBe(texto.campos);
  expect(raios.botoes).toBe(texto.botoes);
  expect(raios.controleSegmentado).toBe(texto.controleSegmentado);
  expect(raios.realceNav).toBe(texto.realceNav);
  expect(raios.pill).toBe(texto.pill);
  expect(`${raios.cardMenor} e ${raios.cardMaior}`).toBe(texto.cards);
});

test("os filtros têm raio 8: pill só nos selos de tier", () => {
  expect(raios.filtros).toBe(8);
  expect(json.raios.regra).toBe("pill só em selos de tier");
});

test("os tamanhos conferem com o texto do JSON", () => {
  const texto = json.tamanhos;
  expect(tamanhos.alvoDeToque).toBe(texto.alvoDeToque);
  expect(tamanhos.campo).toBe(texto.campo);
  expect(tamanhos.iconeNav).toBe(texto.iconeNav);
  expect(tamanhos.avatarNav).toBe(texto.avatarNav);
  expect(tamanhos.avatarPost).toBe(texto.avatarPost);
  expect(tamanhos.medalhaoLista).toBe(texto.medalhaoLista);
  expect(tamanhos.tracoIcone).toBe(texto.tracoIcone);

  const discreto = texto.botaoDiscreto;
  expect(tamanhos.botaoDiscreto.altura).toBe(
    numero(discreto, /^(\d+) de altura visual/),
  );
  expect(tamanhos.botaoDiscreto.texto).toBe(numero(discreto, /texto (\d+)/));
  expect(tamanhos.botaoDiscreto.toque).toBe(numero(discreto, /(\d+) de toque/));

  expect(tamanhos.botaoGrande).toBe(
    numero(texto.botaoGrande, /^(\d+) de altura/),
  );
  expect(tamanhos.navegacaoInferior).toBe(
    numero(texto.navegacaoInferior, /^(\d+) de altura/),
  );
  expect(tamanhos.realceAbaAtiva).toBe(
    numero(texto.realceAbaAtiva, /^(\d+) x \d+/),
  );
  expect(raios.realceNav).toBe(numero(texto.realceAbaAtiva, /raio (\d+)/));
  expect(tamanhos.bolinhaNovidade.diametro).toBe(
    numero(texto.bolinhaNovidade, /^(\d+),/),
  );
  expect(tamanhos.bolinhaNovidade.halo).toBe(
    numero(texto.bolinhaNovidade, /halo de (\d+)px/),
  );
  expect(tamanhos.fotoPost).toBe(numero(texto.fotoPost, /^(\d+) x/));
});

test.each(Object.keys(tipografia) as (keyof typeof tipografia)[])(
  "o estilo de texto %s confere com a escala do JSON",
  (nome) => {
    const estilo: EstiloDeTexto = tipografia[nome];
    const texto = json.tipografia.escala[nome];

    expect(texto.startsWith(`${estilo.tamanho}`)).toBe(true);
    if (estilo.alturaLinha !== undefined) {
      expect(texto).toContain(`${estilo.tamanho}/${estilo.alturaLinha},`);
    }
    expect(texto).toContain(`${estilo.familia} ${estilo.peso}`);
    expect(texto.includes("itálico")).toBe(estilo.italico === true);
    expect(texto.includes("caixa alta")).toBe(estilo.caixaAlta === true);
    if (estilo.espacamentoLetras !== undefined) {
      expect(texto).toContain(`${estilo.espacamentoLetras}em`);
    }
  },
);

import AsyncStorage from "@react-native-async-storage/async-storage";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { useColorScheme } from "react-native";

import { cores, type ThemeColors, type ThemeName } from "./tokens";

export type ThemePreference = "sistema" | ThemeName;

export const THEME_STORAGE_KEY = "maxx.tema";

interface ThemeContextValue {
  preference: ThemePreference;
  setPreference: (preference: ThemePreference) => void;
  // O tema efetivo: a preferência, ou o do aparelho quando ela é "sistema".
  name: ThemeName;
  colors: ThemeColors;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

function parsePreference(stored: string | null): ThemePreference {
  return stored === "claro" || stored === "escuro" ? stored : "sistema";
}

export function ThemeProvider({ children }: { children: ReactNode }) {
  const system = useColorScheme();
  const [preference, setPreferenceState] = useState<ThemePreference | null>(
    null,
  );

  useEffect(() => {
    // Armazenamento indisponível não pode travar o app: fica o padrão, Sistema.
    AsyncStorage.getItem(THEME_STORAGE_KEY)
      .then(parsePreference)
      .catch((): ThemePreference => "sistema")
      .then((loaded) => setPreferenceState((current) => current ?? loaded));
  }, []);

  const setPreference = useCallback((next: ThemePreference) => {
    setPreferenceState(next);
    // Se a gravação falhar, a troca vale até fechar o app.
    AsyncStorage.setItem(THEME_STORAGE_KEY, next).catch(() => {});
  }, []);

  const value = useMemo<ThemeContextValue | null>(() => {
    if (preference === null) return null;
    const systemName: ThemeName = system === "dark" ? "escuro" : "claro";
    const name = preference === "sistema" ? systemName : preference;
    return { preference, setPreference, name, colors: cores[name] };
  }, [preference, setPreference, system]);

  // Até ler a preferência, não pinta nada: evita piscar o tema errado.
  if (value === null) return null;

  return (
    <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
  );
}

export function useTheme(): ThemeContextValue {
  const value = useContext(ThemeContext);
  if (value === null) {
    throw new Error("useTheme precisa estar dentro de ThemeProvider.");
  }
  return value;
}

import { Pressable, StyleSheet, Text, View } from "react-native";

import { useTheme, type ThemePreference } from "./ThemeProvider";
import { raios, tamanhos } from "./tokens";

const OPTIONS: { value: ThemePreference; label: string }[] = [
  { value: "sistema", label: "Sistema" },
  { value: "claro", label: "Claro" },
  { value: "escuro", label: "Escuro" },
];

const TRACK_PADDING = 4;

// Escolha do tema. Fica na tela de status e na vitrine até o passo 7, quando vai para o perfil.
export function ThemePreferenceControl() {
  const { preference, setPreference, name, colors } = useTheme();

  return (
    <View
      role="radiogroup"
      aria-label="Tema"
      style={[styles.track, { backgroundColor: colors.surface }]}
    >
      {OPTIONS.map(({ value, label }) => {
        const selected = value === preference;
        return (
          <Pressable
            key={value}
            role="radio"
            aria-checked={selected}
            aria-label={label}
            onPress={() => setPreference(value)}
            style={[
              styles.segment,
              selected && { backgroundColor: colors.segmentOn },
              // A única sombra da interface: controle segmentado, só no claro.
              selected &&
                name === "claro" && { boxShadow: colors.segmentShadow },
            ]}
          >
            <Text
              style={[
                styles.label,
                { color: selected ? colors.ink : colors.ink2 },
              ]}
            >
              {label}
            </Text>
          </Pressable>
        );
      })}
    </View>
  );
}

const styles = StyleSheet.create({
  track: {
    flexDirection: "row",
    borderRadius: raios.controleSegmentado,
    padding: TRACK_PADDING,
  },
  // Com o trilho, cada segmento chega aos 44 de toque.
  segment: {
    minHeight: tamanhos.alvoDeToque - 2 * TRACK_PADDING,
    paddingHorizontal: 16,
    justifyContent: "center",
    borderRadius: raios.segmentoAtivo,
  },
  label: { fontSize: 13, fontWeight: "600" },
});

import { act, render } from "@testing-library/react-native";
import type { ReactElement } from "react";

import { ThemeProvider } from "../theme/ThemeProvider";

// Renderiza dentro do ThemeProvider e espera a leitura da preferência guardada.
export async function renderWithTheme(ui: ReactElement) {
  const wrap = (element: ReactElement) => (
    <ThemeProvider>{element}</ThemeProvider>
  );
  const result = await render(wrap(ui));
  await act(async () => {});
  return {
    ...result,
    rerender: (element: ReactElement) => result.rerender(wrap(element)),
  };
}

import AsyncStorage from "@react-native-async-storage/async-storage";
import { act, render, screen } from "@testing-library/react-native";
import { Text } from "react-native";

import { renderWithTheme } from "../test/renderWithTheme";
import {
  THEME_STORAGE_KEY,
  useTheme,
  type ThemePreference,
} from "./ThemeProvider";
import { cores } from "./tokens";

let mockSystem: "light" | "dark" = "light";
jest.mock("react-native/Libraries/Utilities/useColorScheme", () => ({
  __esModule: true,
  default: () => mockSystem,
}));

let theme: ReturnType<typeof useTheme>;
function Probe() {
  theme = useTheme();
  return <Text>{theme.name}</Text>;
}

beforeEach(async () => {
  mockSystem = "light";
  await AsyncStorage.clear();
});

test("sem preferência guardada, o padrão é Sistema e segue o aparelho", async () => {
  mockSystem = "dark";
  await renderWithTheme(<Probe />);

  expect(theme.preference).toBe("sistema");
  expect(theme.name).toBe("escuro");
  expect(theme.colors).toEqual(cores.escuro);
});

test("Sistema acompanha a troca de tema do aparelho", async () => {
  const { rerender } = await renderWithTheme(<Probe />);
  expect(theme.name).toBe("claro");

  mockSystem = "dark";
  await rerender(<Probe />);

  expect(theme.name).toBe("escuro");
});

test.each<[ThemePreference, "light" | "dark"]>([
  ["claro", "dark"],
  ["escuro", "light"],
])(
  "a preferência %s vale mesmo com o aparelho em %s",
  async (preference, system) => {
    mockSystem = system;
    await AsyncStorage.setItem(THEME_STORAGE_KEY, preference);
    await renderWithTheme(<Probe />);

    expect(theme.preference).toBe(preference);
    expect(theme.name).toBe(preference);
  },
);

test("a troca aplica na hora e fica guardada", async () => {
  await renderWithTheme(<Probe />);

  await act(async () => theme.setPreference("escuro"));

  expect(screen.getByText("escuro")).toBeTruthy();
  expect(await AsyncStorage.getItem(THEME_STORAGE_KEY)).toBe("escuro");
});

test("valor desconhecido guardado cai no padrão", async () => {
  await AsyncStorage.setItem(THEME_STORAGE_KEY, "sepia");
  await renderWithTheme(<Probe />);

  expect(theme.preference).toBe("sistema");
});

test("falha ao ler o armazenamento não trava o app", async () => {
  jest
    .mocked(AsyncStorage.getItem)
    .mockRejectedValueOnce(new Error("sem disco"));
  await renderWithTheme(<Probe />);

  expect(theme.preference).toBe("sistema");
  expect(screen.getByText("claro")).toBeTruthy();
});

test("falha ao gravar mantém a troca até fechar o app", async () => {
  await renderWithTheme(<Probe />);
  jest
    .mocked(AsyncStorage.setItem)
    .mockRejectedValueOnce(new Error("sem disco"));

  await act(async () => theme.setPreference("escuro"));

  expect(theme.name).toBe("escuro");
});

test("useTheme fora do provedor avisa com erro claro", async () => {
  const silence = jest.spyOn(console, "error").mockImplementation(() => {});

  await expect(render(<Probe />)).rejects.toThrow(/ThemeProvider/);

  silence.mockRestore();
});

import AsyncStorage from "@react-native-async-storage/async-storage";
import { fireEvent, screen } from "@testing-library/react-native";

import { renderWithTheme } from "../test/renderWithTheme";
import { ThemePreferenceControl } from "./ThemePreferenceControl";
import { THEME_STORAGE_KEY } from "./ThemeProvider";

beforeEach(() => AsyncStorage.clear());

test("oferece Sistema, Claro e Escuro, com Sistema marcado por padrão", async () => {
  await renderWithTheme(<ThemePreferenceControl />);

  expect(
    screen.getByRole("radio", { name: "Sistema", checked: true }),
  ).toBeTruthy();
  expect(
    screen.getByRole("radio", { name: "Claro", checked: false }),
  ).toBeTruthy();
  expect(
    screen.getByRole("radio", { name: "Escuro", checked: false }),
  ).toBeTruthy();
});

test("tocar numa opção marca e guarda a escolha", async () => {
  await renderWithTheme(<ThemePreferenceControl />);

  await fireEvent.press(screen.getByRole("radio", { name: "Escuro" }));

  expect(
    screen.getByRole("radio", { name: "Escuro", checked: true }),
  ).toBeTruthy();
  expect(await AsyncStorage.getItem(THEME_STORAGE_KEY)).toBe("escuro");
});

const fs = require("fs");
const root = process.argv[2];
function edit(file, replacements) {
  const path = `${root}/${file}`;
  let text = fs.readFileSync(path, "utf8");
  for (const [from, to] of replacements) {
    if (!text.includes(from)) throw new Error(`${file}: não achei ${from}`);
