import { expect, test } from "@playwright/test";

const FAMILIAS = [
  "Archivo112-700",
  "Archivo112-800",
  "Archivo112-800Italic",
  "InstrumentSans-400",
  "InstrumentSans-500",
  "InstrumentSans-600",
  "InstrumentSans-700",
];

test(
  "as fontes vêm do próprio build, sem CDN, e a Archivo chega em 112%",
  { tag: ["@desktop", "@celular"] },
  async ({ page, baseURL }) => {
    const origem = new URL(baseURL!).origin;
    const fontes: { url: string; status: number }[] = [];
    const deFora: string[] = [];
    page.on("response", (resposta) => {
      if (/\.(ttf|otf|woff2?)(\?|$)/.test(resposta.url())) {
        fontes.push({ url: resposta.url(), status: resposta.status() });
      }
      if (new URL(resposta.url()).origin !== origem) {
        deFora.push(resposta.url());
      }
    });

    await page.goto("/");
    const detalhe = page.getByText("A API respondeu 200.");
    await expect(detalhe).toBeVisible();
    await page.evaluate(() => document.fonts.ready);

    expect(deFora).toEqual([]);
    for (const familia of FAMILIAS) {
      const arquivo = fontes.find((f) => f.url.includes(`/${familia}.`));
      expect(arquivo?.status, `arquivo de ${familia}`).toBe(200);
    }

    // `document.fonts.check` responde true até para fonte inexistente, e uma face fora de uso
    // pode ficar "unloaded" mesmo com o arquivo já baixado: vale pedir a face e ver o que volta.
    const estados = await page.evaluate(
      (familias) =>
        Promise.all(
          familias.map(async (familia) =>
            (await document.fonts.load(`16px "${familia}"`, "M")).map(
              (face) => `${face.family.replace(/"/g, "")}: ${face.status}`,
            ),
          ),
        ),
      FAMILIAS,
    );
    expect(estados.flat()).toEqual(FAMILIAS.map((f) => `${f}: loaded`));

    // A largura óptica chega ao navegador: em Archivo 800, o M tem 1026 unidades em 112%
    // (914 em 100%), então quatro deles a 100 px medem cerca de 410 px.
    const largura = await page.evaluate(() => {
      const medida = document.createElement("span");
      medida.style.cssText =
        'position:absolute;visibility:hidden;font:100px "Archivo112-800"';
      medida.textContent = "MMMM";
      document.body.append(medida);
      const { width } = medida.getBoundingClientRect();
      medida.remove();
      return width;
    });
    expect(Math.abs(largura - 410.4)).toBeLessThan(1);

    // O texto usa a fonte embarcada, não a do sistema.
    await expect(detalhe).toHaveCSS("font-family", /InstrumentSans-500/);
  },
);

/// <reference types="node" />
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

import { fontAssets, fontFamily, textStyles, type FontFamily } from "./fonts";
import { tipografia } from "./tokens";

const PASTA = join(__dirname, "../../assets/fonts");

// Leitor mínimo de sfnt: o suficiente para conferir o que o script de instanciação promete.
function lerFonte(arquivo: string) {
  const dados = readFileSync(join(PASTA, arquivo));
  const tabelas = new Map<string, number>();
  for (let i = 0; i < dados.readUInt16BE(4); i++) {
    const registro = 12 + i * 16;
    tabelas.set(
      dados.toString("latin1", registro, registro + 4),
      dados.readUInt32BE(registro + 8),
    );
  }
  const tabela = (tag: string) => {
    const inicio = tabelas.get(tag);
    if (inicio === undefined) throw new Error(`${arquivo} sem tabela ${tag}`);
    return inicio;
  };

  return {
    temTabela: (tag: string) => tabelas.has(tag),
    peso: dados.readUInt16BE(tabela("OS/2") + 4),
    classeDeLargura: dados.readUInt16BE(tabela("OS/2") + 6),
    anguloItalico: dados.readInt32BE(tabela("post") + 4) / 65536,
    recursos() {
      const gsub = tabela("GSUB");
      const lista = gsub + dados.readUInt16BE(gsub + 6);
      const tags = new Set<string>();
      for (let i = 0; i < dados.readUInt16BE(lista); i++) {
        const registro = lista + 2 + i * 6;
        tags.add(dados.toString("latin1", registro, registro + 4));
      }
      return tags;
    },
    // Registro Windows, em UTF-16 BE.
    nome(id: number) {
      const name = tabela("name");
      const textos = name + dados.readUInt16BE(name + 4);
      for (let i = 0; i < dados.readUInt16BE(name + 2); i++) {
        const registro = name + 6 + i * 12;
        if (
          dados.readUInt16BE(registro) === 3 &&
          dados.readUInt16BE(registro + 6) === id
        ) {
          const inicio = textos + dados.readUInt16BE(registro + 10);
          const fim = inicio + dados.readUInt16BE(registro + 8);
          return Buffer.from(dados.subarray(inicio, fim))
            .swap16()
            .toString("utf16le");
        }
      }
      return undefined;
    },
  };
}

const FAMILIAS = Object.keys(fontAssets) as FontFamily[];

test("cada arquivo da pasta está registrado, e vice-versa", () => {
  const arquivos = readdirSync(PASTA)
    .filter((nome) => nome.endsWith(".ttf"))
    .map((nome) => nome.replace(".ttf", ""));

  expect(arquivos.sort()).toEqual([...FAMILIAS].sort());
});

test("a licença das duas famílias acompanha os arquivos", () => {
  const arquivos = readdirSync(PASTA);

  expect(arquivos).toContain("OFL-Archivo.txt");
  expect(arquivos).toContain("OFL-InstrumentSans.txt");
});

describe.each(FAMILIAS)("%s", (familia) => {
  const fonte = lerFonte(`${familia}.ttf`);
  const archivo = familia.startsWith("Archivo");

  test("é estática, sem eixo variável", () => {
    expect(fonte.temTabela("fvar")).toBe(false);
    expect(fonte.temTabela("gvar")).toBe(false);
  });

  test("tem o peso do nome", () => {
    expect(familia).toContain(`-${fonte.peso}`);
  });

  test("Archivo é semi-expandida, Instrument Sans tem largura normal", () => {
    expect(fonte.classeDeLargura).toBe(archivo ? 6 : 5);
  });

  test("só o arquivo itálico é inclinado", () => {
    expect(fonte.anguloItalico !== 0).toBe(familia.endsWith("Italic"));
  });

  test("oferece algarismos tabulares", () => {
    expect(fonte.recursos().has("tnum")).toBe(true);
  });

  test("tem nome PostScript próprio, que o iOS exige, e traz a licença", () => {
    expect(fonte.nome(6)).toBe(familia);
    expect(fonte.nome(13)).toMatch(/Open Font License/);
  });
});

test.each(Object.keys(tipografia) as (keyof typeof tipografia)[])(
  "o estilo %s aponta para um arquivo registrado, sem depender de fontWeight",
  (nome) => {
    const estilo = textStyles[nome];

    expect(FAMILIAS).toContain(estilo.fontFamily);
    expect(estilo.fontWeight).toBeUndefined();
    expect(estilo.fontSize).toBe(tipografia[nome].tamanho);
  },
);

test("o nome da família sai da família, do peso e do itálico", () => {
  expect(fontFamily({ familia: "Archivo", peso: 800, italico: true })).toBe(
    "Archivo112-800Italic",
  );
  expect(fontFamily({ familia: "Instrument Sans", peso: 600 })).toBe(
    "InstrumentSans-600",
  );
});

test("pontos saem em Archivo 800 itálico com algarismos tabulares", () => {
  expect(textStyles.pontos).toEqual({
    fontFamily: "Archivo112-800Italic",
    fontSize: 18,
    fontVariant: ["tabular-nums"],
  });
});

test("o rótulo vai em caixa alta, com espaçamento de 0,04 em", () => {
  expect(textStyles.rotulo).toMatchObject({
    fontFamily: "InstrumentSans-600",
    fontSize: 11,
    lineHeight: 14,
    textTransform: "uppercase",
    letterSpacing: 11 * 0.04,
  });
});

import json from "../../../../design/tokens.json";

// Camada tipada sobre design/tokens.json, a fonte dos valores. Cores e tiers vêm direto do
// JSON. Tamanhos, raios e tipografia estão lá em texto livre ("28/32, Archivo 800"), então
// viram números aqui; tokens.test.ts confere cada um contra o texto do JSON.

export type ThemeName = "claro" | "escuro";
export type ThemeColors = typeof json.cores.claro;

export const cores: Record<ThemeName, ThemeColors> = {
  claro: json.cores.claro,
  escuro: json.cores.escuro,
};

export type Tier = "bronze" | "prata" | "ouro" | "diamante";
export type Raridade = "comum" | "raro" | "epico" | "lendario";

export interface TierStyle {
  pontos: string;
  medalhao: [string, string, string];
  borda: string;
  glifo: string;
  pill: [string, string, string, string, string];
  pillTexto: string;
  texto: Record<ThemeName, string>;
  fundoGrade: Record<ThemeName, [string, string]>;
}

export const tiers = {
  bronze: json.tiers.bronze,
  prata: json.tiers.prata,
  ouro: json.tiers.ouro,
  diamante: json.tiers.diamante,
} as Record<Tier, TierStyle>;

export const espacamento = {
  base: 4,
  escala: [4, 8, 12, 16, 24, 32],
  margemLateral: 16,
  respiroAntesDaNavegacao: 24,
} as const;

export const raios = {
  filtros: 8,
  campos: 8,
  botoes: 8,
  controleSegmentado: 10,
  // Segmento ativo dentro do trilho (identidade-visual.md); o JSON só traz o raio do trilho.
  segmentoAtivo: 8,
  cardMenor: 12,
  cardMaior: 16,
  realceNav: 14,
  pill: 999,
} as const;

export const tamanhos = {
  alvoDeToque: 44,
  botaoDiscreto: { altura: 32, texto: 13, toque: 44 },
  botaoGrande: 50,
  campo: 48,
  navegacaoInferior: 84,
  iconeNav: 26,
  realceAbaAtiva: 44,
  avatarNav: 30,
  avatarPost: 36,
  medalhaoLista: 48,
  bolinhaNovidade: { diametro: 8, halo: 2 },
  fotoPost: 390,
  tracoIcone: 1.8,
} as const;

export interface EstiloDeTexto {
  familia: "Archivo" | "Instrument Sans";
  tamanho: number;
  // A escala não define altura de linha para os pontos.
  alturaLinha?: number;
  peso: 400 | 500 | 600 | 700 | 800;
  italico?: boolean;
  caixaAlta?: boolean;
  // Em em, como no JSON.
  espacamentoLetras?: number;
  // Vem do uso em tipografia.display no JSON: "pontos em itálico 800 com algarismos tabulares".
  algarismosTabulares?: boolean;
}

export const tipografia = {
  display: { familia: "Archivo", tamanho: 28, alturaLinha: 32, peso: 800 },
  titulo: { familia: "Archivo", tamanho: 22, alturaLinha: 26, peso: 700 },
  pontos: {
    familia: "Archivo",
    tamanho: 18,
    peso: 800,
    italico: true,
    algarismosTabulares: true,
  },
  secao: { familia: "Archivo", tamanho: 15, alturaLinha: 19, peso: 700 },
  corpo: {
    familia: "Instrument Sans",
    tamanho: 14,
    alturaLinha: 20,
    peso: 400,
  },
  legenda: {
    familia: "Instrument Sans",
    tamanho: 12,
    alturaLinha: 16,
    peso: 500,
  },
  rotulo: {
    familia: "Instrument Sans",
    tamanho: 11,
    alturaLinha: 14,
    peso: 600,
    caixaAlta: true,
    espacamentoLetras: 0.04,
  },
} as const satisfies Record<string, EstiloDeTexto>;

import { Pressable, StyleSheet, Text, View } from "react-native";

import { fontFamily } from "./fonts";
import { useTheme, type ThemePreference } from "./ThemeProvider";
import { raios, tamanhos } from "./tokens";

const OPTIONS: { value: ThemePreference; label: string }[] = [
  { value: "sistema", label: "Sistema" },
  { value: "claro", label: "Claro" },
  { value: "escuro", label: "Escuro" },
];

const TRACK_PADDING = 4;

// Escolha do tema. Fica na tela de status e na vitrine até o passo 7, quando vai para o perfil.
export function ThemePreferenceControl() {
  const { preference, setPreference, name, colors } = useTheme();

  return (
    <View
      role="radiogroup"
      aria-label="Tema"
      style={[styles.track, { backgroundColor: colors.surface }]}
    >
      {OPTIONS.map(({ value, label }) => {
        const selected = value === preference;
        return (
          <Pressable
            key={value}
            role="radio"
            aria-checked={selected}
            aria-label={label}
            onPress={() => setPreference(value)}
            style={[
              styles.segment,
              selected && { backgroundColor: colors.segmentOn },
              // A única sombra da interface: controle segmentado, só no claro.
              selected &&
                name === "claro" && { boxShadow: colors.segmentShadow },
            ]}
          >
            <Text
              style={[
                styles.label,
                { color: selected ? colors.ink : colors.ink2 },
              ]}
            >
              {label}
            </Text>
          </Pressable>
        );
      })}
    </View>
  );
}

const styles = StyleSheet.create({
  track: {
    flexDirection: "row",
    borderRadius: raios.controleSegmentado,
    padding: TRACK_PADDING,
  },
  // Com o trilho, cada segmento chega aos 44 de toque.
  segment: {
    minHeight: tamanhos.alvoDeToque - 2 * TRACK_PADDING,
    paddingHorizontal: 16,
    justifyContent: "center",
    borderRadius: raios.segmentoAtivo,
  },
  label: {
    fontFamily: fontFamily({ familia: "Instrument Sans", peso: 600 }),
    fontSize: tamanhos.botaoDiscreto.texto,
  },
});

const fs = require("fs");
const root = process.argv[2];
function edit(file, replacements) {
  const path = `${root}/${file}`;
  let text = fs.readFileSync(path, "utf8");
  for (const [from, to] of replacements) {
    if (!text.includes(from)) throw new Error(`${file}: não achei ${from}`);
    text = text.replace(from, () => to);
  }
  fs.writeFileSync(path, text);
}

