256	    // Quatro bimestres seguidos de 50 dias a partir de `inicio`, com um dia de folga entre eles.
257	    private static AnoLetivo Ano(int ano, DateOnly inicio)
258	    {
259	        Bimestre Bimestre(int numero) =>
260	            new(numero, inicio.AddDays((numero - 1) * 51), inicio.AddDays(((numero - 1) * 51) + 49));
261	
262	        return new AnoLetivo(
263	            ano,
264	            new SemestreLetivo(ano, 1, Bimestre(1), Bimestre(2)),
