284	    // Status, tipo de conteúdo e corpo sem o traceId, que muda a cada pedido.
285	    private static async Task<string> DescreverAsync(HttpResponseMessage response)
286	    {
287	        var texto = await response.Content.ReadAsStringAsync(Ct);
288	        var corpo = string.IsNullOrEmpty(texto)
289	            ? string.Empty
290	            : string.Join(',', JsonDocument.Parse(texto).RootElement.EnumerateObject()
291	                .Where(campo => campo.Name != "traceId").Select(campo => $"{campo.Name}={campo.Value}"));
292	        return $"{(int)response.StatusCode} {response.Content.Headers.ContentType} {corpo}";
293	    }
