295	    private static IEnumerable<string> Chaves(JsonNode no, string prefixo = "")
296	    {
297	        if (no is not JsonObject objeto)
298	        {
299	            yield break;
300	        }
301	
302	        foreach (var (nome, filho) in objeto)
303	        {
304	            var chave = prefixo.Length == 0 ? nome : $"{prefixo}:{nome}";
305	            yield return chave;
306	            if (filho is not null)
307	            {
308	                foreach (var interna in Chaves(filho, chave))
309	                {
310	                    yield return interna;
311	                }
312	            }
313	        }
314	    }
