318	        Assert.Equal(status, response.StatusCode);
319	        using var corpo = JsonDocument.Parse(await response.Content.ReadAsStringAsync(Ct));
320	        Assert.Equal(codigo, corpo.RootElement.GetProperty("codigo").GetString());
321	    }
