export type IconName = keyof typeof ICONES;
export const iconNames = Object.keys(ICONES) as IconName[];

interface IconProps {
  name: IconName;
  // Sempre um token do tema: o ícone não tem cor própria.
  color: string;
  size?: number;
  // Preenchido, como a aba ativa e a curtida; sem isso, contorno.
  filled?: boolean;
  // Cor do desenho interno no preenchido: o fundo sobre o qual o ícone está.
  detailColor?: string;
  // Sem rótulo, o ícone é decorativo: quem lê a tela usa o rótulo do botão em volta.
  label?: string;
}

export function Icon({
  name,
  color,
  size = 24,
  filled = false,
  detailColor,
  label,
}: IconProps) {
  const partes: Parte[] = ICONES[name];

  return (
    <View
      testID={`icone-${name}`}
      {...(label ? { role: "img", "aria-label": label } : { "aria-hidden": true })}
    >
      <Svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        strokeWidth={tamanhos.tracoIcone}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        {partes.map((parte, indice) => {
          const macica = filled && parte.modo === undefined;
          const props = {
            stroke: filled && parte.modo === "detalhe" ? (detailColor ?? color) : color,
            fill: macica ? color : "none",
          };
          if ("d" in parte) return <Path key={indice} d={parte.d} {...props} />;
          if ("r" in parte) {
            return <Circle key={indice} cx={parte.cx} cy={parte.cy} r={parte.r} {...props} />;
          }
          return (
            <Rect
              key={indice}
              x={parte.x}
              y={parte.y}
              width={parte.width}
              height={parte.height}
              rx={parte.rx}
              {...props}
            />
          );
        })}
      </Svg>
    </View>
  );
}
