  expect(
    StyleSheet.flatten(screen.getByTestId("tela").props.style),
  ).toMatchObject({ paddingLeft: 16, paddingRight: 16, paddingBottom: 24 });
  expect(screen.getByText("conteúdo")).toBeTruthy();
});

