  expect(StyleSheet.flatten(tela.props.contentContainerStyle)).toMatchObject({
    paddingLeft: 16,
    paddingBottom: 24,
  });
  expect(StyleSheet.flatten(tela.props.style).paddingBottom).toBeUndefined();
});

