import { Redirect } from "expo-router";
import type { ComponentType } from "react";

// Só em desenvolvimento. Com o `require` atrás do __DEV__, a vitrine nem entra no bundle de
// produção, e a rota volta para o início.
const VitrineScreen: ComponentType | null = __DEV__
  ? require("../vitrine/VitrineScreen").VitrineScreen
  : null;

export default function VitrineRoute() {
  return VitrineScreen ? <VitrineScreen /> : <Redirect href="/" />;
}

import type { ReactElement } from "react";

// A rota decide pelo __DEV__ ao carregar o módulo: cada teste a carrega num registro limpo.
function carregarRota(dev: boolean) {
  const anterior = __DEV__;
  (globalThis as { __DEV__: boolean }).__DEV__ = dev;
  let rota!: () => ReactElement<{ href?: string }>;
  jest.isolateModules(() => {
    rota = require("../app/vitrine").default;
  });
  (globalThis as { __DEV__: boolean }).__DEV__ = anterior;
  return rota;
}

afterEach(() => jest.dontMock("./VitrineScreen"));

test("em produção, a rota volta para o início e nem carrega a vitrine", () => {
  jest.doMock("./VitrineScreen", () => {
    throw new Error("a vitrine não pode carregar em produção");
  });

  const elemento = carregarRota(false)();

  expect(elemento.props.href).toBe("/");
});

test("em desenvolvimento, a rota mostra a vitrine", () => {
  const Marcador = () => null;
  jest.doMock("./VitrineScreen", () => ({ VitrineScreen: Marcador }));

  expect(carregarRota(true)().type).toBe(Marcador);
});

import { expect, test } from "@playwright/test";

test(
  "a vitrine não existe no build de produção",
  { tag: ["@desktop", "@celular"] },
  async ({ page, request }) => {
    await page.goto("/vitrine");

    await expect(page).toHaveURL(/\/$/);
    await expect(page.getByTestId("estado-api")).toBeVisible();

    // O texto da vitrine também não viaja no bundle.
    const scripts = await page
      .locator("script[src]")
      .evaluateAll((tags) => tags.map((tag) => (tag as HTMLScriptElement).src));
    expect(scripts.length).toBeGreaterThan(0);
    for (const script of scripts) {
      const corpo = await (await request.get(script)).text();
      expect(corpo).not.toContain("Só em desenvolvimento");
    }
  },
);

