const { chromium } = require(require.resolve("@playwright/test", { paths: [process.cwd()] }));
const saida = process.argv[2];
(async () => {
  const browser = await chromium.launch();
  for (const scheme of ["light", "dark"]) {
    const page = await (await browser.newContext({ viewport: { width: 390, height: 1200 }, colorScheme: scheme, deviceScaleFactor: 2 })).newPage();
    const erros = [];
    page.on("pageerror", (e) => erros.push(String(e)));
    // Mede o título em cada quadro, para ver se a fonte troca depois da primeira pintura.
    await page.addInitScript(() => {
      window.__larguras = [];
      const passo = () => {
        const alvo = [...document.querySelectorAll("div")].find((d) => d.children.length === 0 && d.textContent === "15.020 pts");
        if (alvo) {
          const r = document.createRange();
          r.selectNodeContents(alvo);
          window.__larguras.push(+r.getBoundingClientRect().width.toFixed(2));
        }
        requestAnimationFrame(passo);
      };
      requestAnimationFrame(passo);
    });
    await page.goto("http://localhost:8083/vitrine", { timeout: 240000 });
    await page.getByText("15.020 pts").waitFor({ timeout: 240000 });
    await page.waitForTimeout(2500);
    const larguras = await page.evaluate(() => window.__larguras);
    const estado = await page.evaluate(() => [...document.fonts].filter((f) => f.family.includes("Archivo")).map((f) => `${f.family} ${f.status}`));
    console.log(scheme, "quadros:", larguras.length, "larguras distintas:", [...new Set(larguras)], estado, "erros:", erros);
    await page.screenshot({ path: `${saida}/etapa3-vitrine-${scheme === "light" ? "claro" : "escuro"}.png`, fullPage: true });
  }
  await browser.close();
})();

