import { useState } from "react";
import { Platform, type ViewStyle } from "react-native";

import { interacao } from "../theme/tokens";

// O anel de foco dos controles: aparece para quem navega por teclado. Na web, um clique de
// mouse também foca o elemento, e por isso vale a regra do navegador (:focus-visible).
export function useFocusRing() {
  const [focusVisible, setFocusVisible] = useState(false);

  return {
    focusVisible,
    focusProps: {
      onFocus: (event: { target?: unknown }) => {
        const alvo = event.target as Element | null | undefined;
        setFocusVisible(
          Platform.OS !== "web" || (alvo?.matches(":focus-visible") ?? true),
        );
      },
      onBlur: () => setFocusVisible(false),
    },
  };
}

export function focusRingStyle(color: string): ViewStyle {
  return {
    outlineColor: color,
    outlineStyle: "solid",
    outlineWidth: interacao.anelDeFoco.espessura,
    outlineOffset: interacao.anelDeFoco.afastamento,
  };
}

// Tira o contorno padrão do navegador, que o anel substitui.
export const noOutline: ViewStyle = { outlineWidth: 0 };

import { Pressable, StyleSheet, Text, View } from "react-native";

import { fontFamily } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { interacao, raios, tamanhos } from "../theme/tokens";
import { focusRingStyle, noOutline, useFocusRing } from "./focusRing";

interface ButtonProps {
  label: string;
  onPress: () => void;
  variant?: "primary" | "secondary";
  // `large` é só o Entrar do login. O discreto ocupa a largura que o pai der.
  size?: "compact" | "large";
  disabled?: boolean;
}

export function Button({
  label,
  onPress,
  variant = "primary",
  size = "compact",
  disabled = false,
}: ButtonProps) {
  const { colors } = useTheme();
  const { focusVisible, focusProps } = useFocusRing();

  const cor = disabled
    ? { fundo: colors.surface2, texto: colors.ink3 }
    : variant === "primary"
      ? { fundo: colors.primaryBg, texto: colors.primaryFg }
      : { fundo: colors.surface, texto: colors.ink };

  return (
    <Pressable
      role="button"
      disabled={disabled}
      onPress={onPress}
      {...focusProps}
      style={[size === "large" ? styles.toqueGrande : styles.toque, noOutline]}
    >
      {({ pressed }) => (
        <View
          testID="botao-visual"
          style={[
            size === "large" ? styles.grande : styles.discreto,
            { backgroundColor: cor.fundo },
            pressed && { opacity: interacao.opacidadePressionado },
            focusVisible && focusRingStyle(colors.focus),
          ]}
        >
          <Text
            numberOfLines={1}
            style={[
              size === "large" ? styles.textoGrande : styles.texto,
              { color: cor.texto },
            ]}
          >
            {label}
          </Text>
        </View>
      )}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  toque: { minHeight: tamanhos.alvoDeToque, justifyContent: "center" },
  toqueGrande: { alignSelf: "stretch" },
  discreto: {
    height: tamanhos.botaoDiscreto.altura,
    borderRadius: raios.botoes,
    paddingHorizontal: 12,
    alignItems: "center",
    justifyContent: "center",
  },
  grande: {
    height: tamanhos.botaoGrande,
    borderRadius: raios.botoes,
    paddingHorizontal: 16,
    alignItems: "center",
    justifyContent: "center",
  },
  texto: {
    fontFamily: fontFamily({ familia: "Instrument Sans", peso: 600 }),
    fontSize: tamanhos.botaoDiscreto.texto,
  },
  // A identidade não dá o tamanho deste texto: 15 é o da escala que mais se aproxima do login.
  textoGrande: {
    fontFamily: fontFamily({ familia: "Instrument Sans", peso: 700 }),
    fontSize: 15,
  },
});

import { fireEvent, screen } from "@testing-library/react-native";
import { StyleSheet, Text } from "react-native";

import { renderWithTheme } from "../test/renderWithTheme";
import { cores } from "../theme/tokens";
import { Button } from "./Button";

const visual = () =>
  StyleSheet.flatten(screen.getByTestId("botao-visual").props.style);
const texto = (label: string) =>
  StyleSheet.flatten(screen.getByText(label).props.style);

test("discreto tem 32 de altura visual, raio 8, texto 13 e 44 de toque", async () => {
  await renderWithTheme(<Button label="Seguir" onPress={() => {}} />);

  expect(visual()).toMatchObject({ height: 32, borderRadius: 8 });
  expect(texto("Seguir").fontSize).toBe(13);
  expect(
    StyleSheet.flatten(screen.getByRole("button", { name: "Seguir" }).props.style)
      .minHeight,
  ).toBe(44);
});

test("grande tem 50 de altura e raio 8", async () => {
  await renderWithTheme(
    <Button label="Entrar" size="large" onPress={() => {}} />,
  );

  expect(visual()).toMatchObject({ height: 50, borderRadius: 8 });
});

test("primário usa a ação do tema; secundário, a superfície", async () => {
  const { rerender } = await renderWithTheme(
    <Button label="Seguir" onPress={() => {}} />,
  );
  expect(visual().backgroundColor).toBe(cores.claro.primaryBg);
  expect(texto("Seguir").color).toBe(cores.claro.primaryFg);

  await rerender(
    <Button label="Seguir" variant="secondary" onPress={() => {}} />,
  );
  expect(visual().backgroundColor).toBe(cores.claro.surface);
  expect(texto("Seguir").color).toBe(cores.claro.ink);
});

test("tocar chama a ação", async () => {
  const onPress = jest.fn();
  await renderWithTheme(<Button label="Seguir" onPress={onPress} />);

  await fireEvent.press(screen.getByRole("button", { name: "Seguir" }));

  expect(onPress).toHaveBeenCalledTimes(1);
});

test("desativado fica em surface2 e ink3 e não responde", async () => {
  const onPress = jest.fn();
  await renderWithTheme(<Button label="Seguir" onPress={onPress} disabled />);

  expect(visual().backgroundColor).toBe(cores.claro.surface2);
  expect(texto("Seguir").color).toBe(cores.claro.ink3);

  await fireEvent.press(
    screen.getByRole("button", { name: "Seguir", disabled: true }),
  );
  expect(onPress).not.toHaveBeenCalled();
});

test("pressionado fica com opacidade 0,85 e volta ao soltar", async () => {
  await renderWithTheme(<Button label="Seguir" onPress={() => {}} />);
  const botao = screen.getByRole("button", { name: "Seguir" });
  expect(visual().opacity).toBeUndefined();

  await fireEvent(botao, "pressIn");
  expect(visual().opacity).toBe(0.85);

  await fireEvent(botao, "pressOut");
  expect(visual().opacity).toBeUndefined();
});

test("em foco, ganha o anel do token com 2 px de afastamento, e perde ao sair", async () => {
  await renderWithTheme(<Button label="Seguir" onPress={() => {}} />);
  const botao = screen.getByRole("button", { name: "Seguir" });
  expect(visual().outlineWidth).toBeUndefined();

  await fireEvent(botao, "focus", {});
  expect(visual()).toMatchObject({
    outlineColor: cores.claro.focus,
    outlineWidth: 2,
    outlineOffset: 2,
  });

  await fireEvent(botao, "blur");
  expect(visual().outlineWidth).toBeUndefined();
});

test("o texto é o rótulo, sem elemento a mais", async () => {
  await renderWithTheme(<Button label="Seguir" onPress={() => {}} />);

  expect(screen.getByText("Seguir").type).toBe(Text.displayName ?? "Text");
});

import { useState } from "react";
import {
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
  type TextInputProps,
} from "react-native";

import { fontFamily } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { interacao, raios, tamanhos } from "../theme/tokens";
import { focusRingStyle, noOutline, useFocusRing } from "./focusRing";
import { Icon } from "./Icon";

interface TextFieldProps extends Omit<
  TextInputProps,
  "style" | "editable" | "secureTextEntry" | "placeholderTextColor"
> {
  label: string;
  // Esconde o texto e oferece o botão de mostrar.
  password?: boolean;
  disabled?: boolean;
}

const RECUO = 14;

export function TextField({
  label,
  password = false,
  disabled = false,
  onFocus,
  onBlur,
  ...input
}: TextFieldProps) {
  const { colors } = useTheme();
  const [focused, setFocused] = useState(false);
  const [revealed, setRevealed] = useState(false);
  const borda = focused
    ? interacao.bordaDeCampoEmFoco
    : interacao.bordaDeCampo;

  return (
    <View style={styles.coluna}>
      <Text style={[styles.rotulo, { color: colors.ink }]}>{label}</Text>
      <View
        testID="campo-caixa"
        style={[
          styles.caixa,
          {
            borderWidth: borda,
            borderColor: focused ? colors.focus : colors.fieldLine,
            backgroundColor: disabled ? colors.surface2 : colors.fieldBg,
            // A borda mais grossa do foco não pode empurrar o texto.
            paddingLeft: RECUO - borda,
          },
        ]}
      >
        <TextInput
          autoCapitalize={password ? "none" : undefined}
          autoCorrect={password ? false : undefined}
          {...input}
          aria-label={label}
          editable={!disabled}
          secureTextEntry={password && !revealed}
          placeholderTextColor={colors.ink3}
          onFocus={(event) => {
            setFocused(true);
            onFocus?.(event);
          }}
          onBlur={(event) => {
            setFocused(false);
            onBlur?.(event);
          }}
          style={[
            styles.entrada,
            noOutline,
            { color: disabled ? colors.ink3 : colors.ink },
          ]}
        />
        {password && (
          <RevealButton
            revealed={revealed}
            disabled={disabled}
            onPress={() => setRevealed((atual) => !atual)}
          />
        )}
      </View>
    </View>
  );
}

function RevealButton({
  revealed,
  disabled,
  onPress,
}: {
  revealed: boolean;
  disabled: boolean;
  onPress: () => void;
}) {
  const { colors } = useTheme();
  const { focusVisible, focusProps } = useFocusRing();

  return (
    <Pressable
      role="button"
      aria-label={revealed ? "Ocultar senha" : "Mostrar senha"}
      disabled={disabled}
      onPress={onPress}
      {...focusProps}
      style={({ pressed }) => [
        styles.mostrar,
        noOutline,
        pressed && { opacity: interacao.opacidadePressionado },
        focusVisible && focusRingStyle(colors.focus),
      ]}
    >
      <Icon
        name={revealed ? "eyeOff" : "eye"}
        color={disabled ? colors.ink3 : colors.ink2}
      />
    </Pressable>
  );
}

const styles = StyleSheet.create({
  coluna: { gap: 8 },
  rotulo: {
    fontFamily: fontFamily({ familia: "Instrument Sans", peso: 600 }),
    fontSize: 14,
    lineHeight: 20,
  },
  caixa: {
    height: tamanhos.campo,
    borderRadius: raios.campos,
    flexDirection: "row",
    alignItems: "center",
  },
  // 16 fora da escala: abaixo disso, o Safari do iPhone dá zoom na tela ao focar o campo.
  entrada: {
    flex: 1,
    height: "100%",
    paddingVertical: 0,
    paddingHorizontal: 0,
    paddingRight: RECUO,
    fontFamily: fontFamily({ familia: "Instrument Sans", peso: 400 }),
    fontSize: 16,
  },
  mostrar: {
    width: tamanhos.alvoDeToque,
    height: tamanhos.alvoDeToque,
    borderRadius: raios.campos,
    alignItems: "center",
    justifyContent: "center",
  },
});

import { fireEvent, screen } from "@testing-library/react-native";
import { StyleSheet } from "react-native";

import { renderWithTheme } from "../test/renderWithTheme";
import { cores } from "../theme/tokens";
import { TextField } from "./TextField";

const caixa = () =>
  StyleSheet.flatten(screen.getByTestId("campo-caixa").props.style);
const campo = (name: string) => screen.getByLabelText(name);

test("tem 48 de altura, raio 8 e borda fieldLine", async () => {
  await renderWithTheme(<TextField label="RA ou e-mail" />);

  expect(caixa()).toMatchObject({
    height: 48,
    borderRadius: 8,
    borderWidth: 1,
    borderColor: cores.claro.fieldLine,
    backgroundColor: cores.claro.fieldBg,
  });
