const OPCOES = [
  { value: "entrar", label: "Entrar" },
  { value: "cadastrar", label: "Cadastrar" },
] as const;

function Controle({
  onChange = () => {},
  disabled,
}: {
  onChange?: (value: string) => void;
  disabled?: boolean;
}) {
  return (
    <SegmentedControl
      label="Acesso"
      options={OPCOES}
      value="entrar"
      onChange={onChange}
      disabled={disabled}
    />
  );
}

