// Uso (de dentro de e2e/): node <este arquivo> <pasta das capturas>
const { chromium } = require(require.resolve("@playwright/test", { paths: [process.cwd()] }));
const saida = process.argv[2];
(async () => {
  const browser = await chromium.launch();
  for (const [scheme, tema] of [["light", "claro"], ["dark", "escuro"]]) {
    const page = await (await browser.newContext({ viewport: { width: 390, height: 844 }, colorScheme: scheme, deviceScaleFactor: 2 })).newPage();
    const erros = [];
    page.on("pageerror", (e) => erros.push(String(e)));
    page.on("console", (m) => { if (m.type() === "error") erros.push(m.text().slice(0, 200)); });
    await page.goto("http://localhost:8083/vitrine", { timeout: 240000 });
    await page.getByText("Botões", { exact: true }).waitFor({ timeout: 240000 });
    const inicio = page.getByText("Botões", { exact: true });
    await inicio.scrollIntoViewIfNeeded();

    // Campo em foco, com a senha aparecendo: mostra borda de 1,5 e o olho alternado.
    await page.getByLabel("RA ou e-mail").click();
