// Serve um build web com o mesmo fallback do Caddy, sem API. Uso: node static-spa.js <pasta> <porta>
const http = require("http");
const fs = require("fs");
const path = require("path");
const [raiz, porta] = process.argv.slice(2);
const tipos = { ".html": "text/html", ".js": "text/javascript", ".ttf": "font/ttf", ".png": "image/png", ".ico": "image/x-icon", ".json": "application/json" };
http
  .createServer((req, res) => {
    const rota = decodeURIComponent(new URL(req.url, "http://x").pathname);
    if (rota.startsWith("/api/")) {
      res.writeHead(503).end();
      return;
    }
    let arquivo = path.join(raiz, rota);
    if (!fs.existsSync(arquivo) || fs.statSync(arquivo).isDirectory()) arquivo = path.join(raiz, "index.html");
    res.writeHead(200, { "content-type": tipos[path.extname(arquivo)] ?? "application/octet-stream" });
    fs.createReadStream(arquivo).pipe(res);
  })
  .listen(+porta);

