import { StyleSheet, Text, View } from "react-native";

import { fontFamily } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { raios, tamanhos } from "../theme/tokens";

interface AvatarProps {
  // Nome de exibição: as iniciais saem dele. Fotos entram quando existirem.
  nome: string;
  size?: number;
}

// Só com as cores do token: aluno nunca é pintado com cor de tier. O anel dourado do próprio
// aluno fica para os passos 7 e 11.
export function Avatar({ nome, size = tamanhos.avatarPost }: AvatarProps) {
  const { colors } = useTheme();

  return (
    <View
      accessible
      role="img"
      aria-label={nome}
      style={[
        styles.circulo,
        {
          width: size,
          height: size,
          backgroundColor: colors.avatarBg,
        },
      ]}
    >
      <Text
        numberOfLines={1}
        style={[
          styles.iniciais,
          { color: colors.avatarFg, fontSize: Math.round(size * 0.4) },
        ]}
      >
        {iniciais(nome)}
      </Text>
    </View>
  );
}

// Primeira letra do primeiro e do último nome: "Ana Paula Souza" vira AS.
export function iniciais(nome: string) {
  const nomes = nome.trim().split(/\s+/);
  const primeira = (palavra: string | undefined) =>
    Array.from(palavra ?? "")[0] ?? "";
  const ultimo = nomes.length > 1 ? nomes[nomes.length - 1] : undefined;
  return (primeira(nomes[0]) + primeira(ultimo)).toLocaleUpperCase("pt-BR");
}

const styles = StyleSheet.create({
  circulo: {
    borderRadius: raios.pill,
    alignItems: "center",
    justifyContent: "center",
  },
  iniciais: {
    fontFamily: fontFamily({ familia: "Archivo", peso: 700 }),
  },
});

import { screen } from "@testing-library/react-native";
import { StyleSheet } from "react-native";

import { renderWithTheme } from "../test/renderWithTheme";
import { cores, tamanhos } from "../theme/tokens";
import { Avatar, iniciais } from "./Avatar";

test.each([
  ["Ana Souza", "AS"],
  ["Ana Paula Souza", "AS"],
  ["  ana  souza ", "AS"],
  ["Ana", "A"],
  ["Élida Ângelo", "ÉÂ"],
])("as iniciais de %j são %s", (nome, esperado) => {
  expect(iniciais(nome)).toBe(esperado);
});

test("usa só as cores do token e o tamanho pedido", async () => {
  await renderWithTheme(<Avatar nome="Ana Souza" size={tamanhos.avatarNav} />);

  expect(
    StyleSheet.flatten(
      screen.getByRole("img", { name: "Ana Souza" }).props.style,
    ),
  ).toMatchObject({
    width: 30,
    height: 30,
    backgroundColor: cores.claro.avatarBg,
  });
  expect(StyleSheet.flatten(screen.getByText("AS").props.style).color).toBe(
    cores.claro.avatarFg,
  );
});

test("o tamanho padrão é o do post", async () => {
  await renderWithTheme(<Avatar nome="Ana Souza" />);

  expect(
    StyleSheet.flatten(screen.getByRole("img").props.style).width,
  ).toBe(36);
});

import type { ReactNode } from "react";
import { Pressable, StyleSheet, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { useTheme } from "../theme/ThemeProvider";
import { interacao, raios, tamanhos } from "../theme/tokens";
import { Avatar } from "./Avatar";
import { focusRingStyle, noOutline, useFocusRing } from "./focusRing";
import { Icon, type IconName } from "./Icon";

export type Aba = "home" | "busca" | "mural" | "trofeus" | "perfil";

const ABAS_COM_ICONE: { aba: Exclude<Aba, "perfil">; rotulo: string; icone: IconName }[] =
  [
    { aba: "home", rotulo: "Home", icone: "home" },
    { aba: "busca", rotulo: "Busca", icone: "search" },
    { aba: "mural", rotulo: "Mural", icone: "newspaper" },
    { aba: "trofeus", rotulo: "Troféus", icone: "taca" },
  ];

interface BottomNavProps {
  active: Aba;
  onSelect: (aba: Aba) => void;
  // Nome do aluno, para o avatar da aba Perfil.
  nome: string;
  // Aviso não lido no Mural; prêmio novo em Troféus.
  novidades?: Partial<Record<"mural" | "trofeus", boolean>>;
}

const RESPIRO_NO_TOPO = 8;
// O que a aba precisa acima da área segura. Com os 34 do iPhone de referência, dá os 84.
const ALTURA_SEM_AREA_SEGURA = 50;

export function BottomNav({
  active,
  onSelect,
  nome,
  novidades = {},
}: BottomNavProps) {
  const { colors } = useTheme();
  const insets = useSafeAreaInsets();

  return (
    <View
      role="tablist"
      testID="navegacao"
      style={[
        styles.barra,
        {
          // 84 de mínimo; cresce só se a área segura do aparelho exigir.
          height: Math.max(
            tamanhos.navegacaoInferior,
            ALTURA_SEM_AREA_SEGURA + insets.bottom,
          ),
          backgroundColor: colors.bg,
          borderTopColor: colors.line,
        },
      ]}
    >
      {ABAS_COM_ICONE.map(({ aba, rotulo, icone }) => {
        const ativa = aba === active;
        return (
          <Tab
            key={aba}
            rotulo={rotulo}
            ativa={ativa}
            novidade={
              (aba === "mural" || aba === "trofeus") && !!novidades[aba]
            }
            onPress={() => onSelect(aba)}
          >
            <Icon
              name={icone}
              size={tamanhos.iconeNav}
              color={ativa ? colors.ink : colors.ink2}
              filled={ativa}
              detailColor={colors.navHighlight}
            />
          </Tab>
        );
      })}
      <Tab
        rotulo="Perfil"
        ativa={active === "perfil"}
        novidade={false}
        onPress={() => onSelect("perfil")}
      >
        <Avatar nome={nome} size={tamanhos.avatarNav} />
      </Tab>
    </View>
  );
}

function Tab({
  rotulo,
  ativa,
  novidade,
  onPress,
  children,
}: {
  rotulo: string;
  ativa: boolean;
  novidade: boolean;
  onPress: () => void;
  children: ReactNode;
}) {
  const { colors } = useTheme();
  const { focusVisible, focusProps } = useFocusRing();

  return (
    <Pressable
      role="tab"
      aria-selected={ativa}
      // A bolinha sozinha não diz nada a quem não vê.
      aria-label={novidade ? `${rotulo}, com novidade` : rotulo}
      onPress={onPress}
      {...focusProps}
      style={[styles.aba, noOutline]}
    >
      {({ pressed }) => (
        <View
          testID={`realce-${rotulo}`}
          style={[
            styles.realce,
            ativa && { backgroundColor: colors.navHighlight },
            pressed && { opacity: interacao.opacidadePressionado },
            focusVisible && focusRingStyle(colors.focus),
          ]}
        >
          <View>
            {children}
            {novidade && (
              <View
                testID={`novidade-${rotulo}`}
                style={[
                  styles.bolinha,
                  { backgroundColor: colors.gold, borderColor: colors.bg },
                ]}
              />
            )}
          </View>
        </View>
      )}
    </Pressable>
  );
}

const { diametro, halo } = tamanhos.bolinhaNovidade;

const styles = StyleSheet.create({
  barra: {
    flexDirection: "row",
    borderTopWidth: 1,
    paddingTop: RESPIRO_NO_TOPO,
  },
  aba: { flex: 1, alignItems: "center" },
  realce: {
    width: tamanhos.realceAbaAtiva,
    height: tamanhos.realceAbaAtiva,
    borderRadius: raios.realceNav,
    alignItems: "center",
    justifyContent: "center",
  },
  // A borda é o halo, na cor do fundo: separa o ouro do que estiver atrás.
  bolinha: {
    position: "absolute",
    top: -halo - 1,
    right: -halo - 1,
    width: diametro + 2 * halo,
    height: diametro + 2 * halo,
    borderRadius: raios.pill,
    borderWidth: halo,
  },
});

import { fireEvent, render, screen } from "@testing-library/react-native";
import type { ComponentProps } from "react";
import { act } from "react";
import { StyleSheet } from "react-native";
import { SafeAreaProvider } from "react-native-safe-area-context";

import { ThemeProvider } from "../theme/ThemeProvider";
import { cores } from "../theme/tokens";
import { BottomNav } from "./BottomNav";

async function renderNav(
  props: Partial<ComponentProps<typeof BottomNav>> = {},
  bottom = 0,
) {
  await render(
    <SafeAreaProvider
      initialMetrics={{
        insets: { top: 0, bottom, left: 0, right: 0 },
        frame: { x: 0, y: 0, width: 390, height: 844 },
      }}
    >
      <ThemeProvider>
        <BottomNav
          active="home"
          onSelect={() => {}}
          nome="Ana Souza"
          {...props}
        />
      </ThemeProvider>
    </SafeAreaProvider>,
  );
  await act(async () => {});
}

const barra = () =>
  StyleSheet.flatten(screen.getByTestId("navegacao").props.style);
const realce = (rotulo: string) =>
  StyleSheet.flatten(screen.getByTestId(`realce-${rotulo}`).props.style);

test("traz as cinco abas, na ordem da identidade", async () => {
  await renderNav();

  expect(screen.getAllByRole("tab").map((aba) => aba.props["aria-label"])).toEqual(
    ["Home", "Busca", "Mural", "Troféus", "Perfil"],
  );
});

test("tem 84 de altura e borda superior de 1 px em line", async () => {
  await renderNav();

  expect(barra()).toMatchObject({
    height: 84,
    borderTopWidth: 1,
    borderTopColor: cores.claro.line,
  });
});

test.each([
  [0, 84],
  [34, 84],
  [48, 98],
])("com área segura de %i, a altura é %i", async (bottom, altura) => {
  await renderNav({}, bottom);

  expect(barra().height).toBe(altura);
});

test("a aba ativa tem realce de 44 x 44, raio 14, em navHighlight", async () => {
  await renderNav({ active: "mural" });

  expect(realce("Mural")).toMatchObject({
    width: 44,
    height: 44,
    borderRadius: 14,
    backgroundColor: cores.claro.navHighlight,
  });
  expect(realce("Home").backgroundColor).toBeUndefined();
  expect(screen.getByRole("tab", { name: "Mural", selected: true })).toBeTruthy();
  expect(screen.getByRole("tab", { name: "Home", selected: false })).toBeTruthy();
});

test("Perfil ativo mantém o avatar sobre o realce", async () => {
  await renderNav({ active: "perfil" });

  expect(realce("Perfil").backgroundColor).toBe(cores.claro.navHighlight);
  expect(screen.getByText("AS")).toBeTruthy();
});

test("tocar uma aba avisa qual foi", async () => {
  const onSelect = jest.fn();
  await renderNav({ onSelect });

  await fireEvent.press(screen.getByRole("tab", { name: "Troféus" }));
  expect(onSelect).toHaveBeenLastCalledWith("trofeus");

  await fireEvent.press(screen.getByRole("tab", { name: "Perfil" }));
  expect(onSelect).toHaveBeenLastCalledWith("perfil");
});

test("a novidade é uma bolinha de 8 em gold, com halo de 2 na cor do fundo, e também vai no rótulo", async () => {
  await renderNav({ novidades: { mural: true } });

  expect(
    StyleSheet.flatten(screen.getByTestId("novidade-Mural").props.style),
  ).toMatchObject({
    width: 12,
    height: 12,
    borderWidth: 2,
    backgroundColor: cores.claro.gold,
    borderColor: cores.claro.bg,
  });
  expect(screen.getByRole("tab", { name: "Mural, com novidade" })).toBeTruthy();
  expect(screen.queryByTestId("novidade-Troféus")).toBeNull();
});

test("a novidade aparece também na aba ativa", async () => {
  await renderNav({ active: "trofeus", novidades: { trofeus: true } });

  expect(screen.getByTestId("novidade-Troféus")).toBeTruthy();
});

test("em foco, o realce ganha o anel do token", async () => {
  await renderNav();

  await fireEvent(screen.getByRole("tab", { name: "Busca" }), "focus", {});

  expect(realce("Busca")).toMatchObject({
    outlineColor: cores.claro.focus,
    outlineWidth: 2,
    outlineOffset: 2,
  });
});

import { StyleSheet, Text, View } from "react-native";

import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { Button } from "./Button";
import { Icon, type IconName } from "./Icon";

const TAMANHO_DO_ICONE = 32;

interface EmptyStateProps {
  title: string;
  message?: string;
  icon?: IconName;
  // Uma saída para quem chegou aqui, quando houver.
  action?: { label: string; onPress: () => void };
}

export function EmptyState({
  title,
  message,
  icon = "inbox",
  action,
}: EmptyStateProps) {
  const { colors } = useTheme();

  return (
    <StateLayout
      icon={<Icon name={icon} color={colors.ink2} size={TAMANHO_DO_ICONE} />}
      title={title}
      message={message}
      action={action}
    />
  );
}

interface ErrorStateProps {
  title?: string;
  message?: string;
  // Sem isso, a tela só informa. Com isso, oferece tentar de novo.
  onRetry?: () => void;
}

// Todo erro em tela vira isto: mensagem amigável, nunca o erro cru. `like` só no ícone.
export function ErrorState({
  title = "Não deu certo agora.",
  message = "Tente de novo em instantes.",
  onRetry,
}: ErrorStateProps) {
  const { colors } = useTheme();

  return (
    <StateLayout
      role="alert"
      icon={<Icon name="alert" color={colors.like} size={TAMANHO_DO_ICONE} />}
      title={title}
      message={message}
      action={
        onRetry ? { label: "Tentar de novo", onPress: onRetry } : undefined
      }
    />
  );
}

function StateLayout({
  role,
  icon,
  title,
  message,
  action,
}: {
  role?: "alert";
  icon: React.ReactNode;
  title: string;
  message?: string;
  action?: { label: string; onPress: () => void };
}) {
  const { colors } = useTheme();

  return (
    <View role={role} style={styles.coluna}>
      {icon}
      <View style={styles.textos}>
        <Text style={[styles.centro, textStyles.secao, { color: colors.ink }]}>
          {title}
        </Text>
        {message && (
          <Text
            style={[styles.centro, textStyles.corpo, { color: colors.ink2 }]}
          >
            {message}
          </Text>
        )}
      </View>
      {action && (
        <Button
          label={action.label}
          variant="secondary"
          onPress={action.onPress}
        />
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  coluna: {
    alignItems: "center",
    paddingVertical: 32,
    paddingHorizontal: 16,
    gap: 12,
  },
  textos: { alignItems: "center", gap: 4 },
  centro: { textAlign: "center" },
});

import { fireEvent, screen } from "@testing-library/react-native";
import { StyleSheet, View } from "react-native";

import { renderWithTheme } from "../test/renderWithTheme";
import { cores } from "../theme/tokens";
import { EmptyState, ErrorState } from "./StateMessage";

const OCULTOS = { includeHiddenElements: true };
const cor = (texto: string) =>
  StyleSheet.flatten(screen.getByText(texto).props.style).color;

// O SVG é nativo: aqui, o caminho vira uma View que mostra o traço pedido.
jest.mock("react-native-svg", () => {
  const { createElement } = jest.requireActual("react");
  const { View: Vista } = jest.requireActual("react-native");
  function elemento(tipo: string) {
    return function ElementoSvg(props: object) {
      return createElement(Vista, { testID: tipo, ...props });
    };
  }
  return {
    __esModule: true,
    default: elemento("svg"),
    Path: elemento("path"),
    Circle: elemento("circle"),
    Rect: elemento("rect"),
  };
});

test("vazio mostra título, explicação e o ícone em ink2", async () => {
  await renderWithTheme(
    <EmptyState title="Nenhum aviso" message="Os avisos aparecem aqui." />,
  );

  expect(cor("Nenhum aviso")).toBe(cores.claro.ink);
  expect(cor("Os avisos aparecem aqui.")).toBe(cores.claro.ink2);
  expect(screen.getByTestId("icone-inbox", OCULTOS)).toBeTruthy();
  expect(screen.getAllByTestId("path", OCULTOS)[0]?.props.stroke).toBe(
    cores.claro.ink2,
  );
  expect(screen.queryByRole("button")).toBeNull();
});

test("vazio pode oferecer uma saída", async () => {
  const onPress = jest.fn();
  await renderWithTheme(
    <EmptyState title="Nada aqui" action={{ label: "Buscar", onPress }} />,
  );

  await fireEvent.press(screen.getByRole("button", { name: "Buscar" }));

  expect(onPress).toHaveBeenCalledTimes(1);
});

test("erro traz mensagem amigável por padrão e é anunciado", async () => {
  await renderWithTheme(<ErrorState />);

  expect(screen.getByRole("alert")).toBeTruthy();
  expect(screen.getByText("Não deu certo agora.")).toBeTruthy();
  expect(screen.getByText("Tente de novo em instantes.")).toBeTruthy();
});

test("like fica só no ícone do erro, nunca no texto", async () => {
  await renderWithTheme(<ErrorState title="Falhou" message="Tente depois." />);

  expect(screen.getAllByTestId("circle", OCULTOS)[0]?.props.stroke).toBe(
    cores.claro.like,
  );
  expect(cor("Falhou")).toBe(cores.claro.ink);
  expect(cor("Tente depois.")).toBe(cores.claro.ink2);
});

test("tentar de novo só aparece com a ação, e a chama", async () => {
  const onRetry = jest.fn();
  const { rerender } = await renderWithTheme(<ErrorState />);
  expect(screen.queryByRole("button")).toBeNull();

  await rerender(<ErrorState onRetry={onRetry} />);
  await fireEvent.press(screen.getByRole("button", { name: "Tentar de novo" }));

  expect(onRetry).toHaveBeenCalledTimes(1);
});

test("o nome do módulo não esconde o View nativo", () => {
  expect(View).toBeDefined();
});

