const { chromium } = require(require.resolve("@playwright/test", { paths: [process.cwd()] }));
const saida = process.argv[2];
(async () => {
  const browser = await chromium.launch();
  for (const [scheme, tema] of [["light", "claro"], ["dark", "escuro"]]) {
    const page = await (await browser.newContext({ viewport: { width: 390, height: 844 }, colorScheme: scheme, deviceScaleFactor: 2 })).newPage();
    const erros = [];
    page.on("pageerror", (e) => erros.push(String(e)));
    page.on("console", (m) => { if (m.type() === "error") erros.push(m.text().slice(0, 220)); });
    await page.goto("http://localhost:8083/vitrine", { timeout: 240000 });
    await page.getByText("Navegação", { exact: true }).waitFor({ timeout: 240000 });
    await page.getByTestId("navegacao").scrollIntoViewIfNeeded();
    await page.getByText("Avatar", { exact: true }).evaluate((e) => e.scrollIntoView({ block: "start" }));
    await page.waitForTimeout(200);
    await page.screenshot({ path: `${saida}/etapa5-${tema}-estrutura.png` });

    // Outra aba ativa, Perfil no fim, e foco por teclado.
    await page.getByRole("tab", { name: "Perfil" }).click();
    await page.keyboard.press("Shift+Tab");
    await page.waitForTimeout(100);
    const nav = await page.getByTestId("navegacao").boundingBox();
    await page.screenshot({
      path: `${saida}/etapa5-${tema}-nav-perfil.png`,
      clip: { x: 0, y: Math.max(0, nav.y - 12), width: 390, height: nav.height + 24 },
    });

    const medidas = await page.evaluate(() => {
      const caixa = (id) => {
        const r = document.querySelector(`[data-testid="${id}"]`).getBoundingClientRect();
        return { x: r.x, y: r.y, w: r.width, h: r.height };
      };
      return {
        nav: caixa("navegacao"),
        realce: caixa("realce-Perfil"),
        bolinha: caixa("novidade-Mural"),
        realceMural: caixa("realce-Mural"),
      };
    });
    console.log(tema, JSON.stringify(medidas), "erros:", erros);
  }
  await browser.close();
})();

