// Uso (de dentro de e2e/): node <este arquivo> <pasta das capturas>
const { chromium } = require(require.resolve("@playwright/test", { paths: [process.cwd()] }));
const saida = process.argv[2];
(async () => {
  const browser = await chromium.launch();
  for (const [scheme, tema] of [["light", "claro"], ["dark", "escuro"]]) {
    const page = await (await browser.newContext({ viewport: { width: 390, height: 1100 }, colorScheme: scheme, deviceScaleFactor: 2 })).newPage();
    const erros = [];
    page.on("pageerror", (e) => erros.push(String(e)));
    page.on("console", (m) => { if (m.type() === "error") erros.push(m.text().slice(0, 220)); });
    await page.goto("http://localhost:8083/vitrine", { timeout: 240000 });
    await page.getByText("Selos", { exact: true }).waitFor({ timeout: 240000 });
    await page.getByText("Medalhões: tier e raridade", { exact: true }).evaluate((e) => e.scrollIntoView({ block: "start" }));
    await page.waitForTimeout(300);
    await page.screenshot({ path: `${saida}/etapa6-${tema}-premios.png` });
    await page.getByText("Trilhas", { exact: true }).evaluate((e) => e.scrollIntoView({ block: "start" }));
    await page.waitForTimeout(200);
    await page.screenshot({ path: `${saida}/etapa6-${tema}-trilhas.png`, clip: { x: 0, y: 0, width: 390, height: 620 } });

    // A trilha de cinco passos precisa rolar; a de quatro cabe inteira.
    const rolagem = await page.evaluate(() =>
      [...document.querySelectorAll('[data-testid="trilha"]')].map((trilha) => {
        const areas = [...trilha.querySelectorAll("div")].filter((d) => getComputedStyle(d).overflowX === "auto" || getComputedStyle(d).overflowX === "scroll");
        const a = areas[0];
        return a ? { visivel: a.clientWidth, total: a.scrollWidth } : null;
      }),
    );
    console.log(tema, "rolagem:", JSON.stringify(rolagem), "erros:", erros);
  }
  await browser.close();
})();

