// Confere se os cortes do XX ficam abertos de ponta a ponta: rasteriza o SVG a 8x e percorre cada
// eixo, marcando o maior alfa encontrado. Uso: node continuidade.js <svg> <dir e2e>
const fs = require("fs");
const { chromium } = require(require.resolve("@playwright/test", { paths: [process.argv[3]] }));
const { PNG } = require(require.resolve("pngjs", { paths: [__dirname] }));
const CORTES = {
  "corte de cima": [[283.5, 2.5], [277.5, 9.5], [272.5, 14.5], [267.5, 19.5], [264.5, 22.5]],
  "corte entre os X": [[285.5, 14.5], [281.5, 18.5], [275.5, 24.5], [270.5, 29.5], [268.5, 31.5]],
};
(async () => {
  const F = 8;
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 338 * F, height: 89 * F } });
  const src = "data:image/svg+xml;base64," + fs.readFileSync(process.argv[2]).toString("base64");
  await p.setContent(`<body style="margin:0;background:transparent"><img src="${src}" style="display:block;width:${338 * F}px;height:${89 * F}px"></body>`);
  await p.waitForTimeout(200);
  const r = PNG.sync.read(await p.screenshot({ omitBackground: true }));
  for (const [nome, pontos] of Object.entries(CORTES)) {
    let maior = 0;
    let amostras = 0;
    for (let i = 0; i < pontos.length - 1; i++) {
      const [ax, ay] = pontos[i];
      const [bx, by] = pontos[i + 1];
      for (let t = 0; t <= 1; t += 0.01) {
        const x = Math.round((ax + (bx - ax) * t) * F);
        const y = Math.round((ay + (by - ay) * t) * F);
        maior = Math.max(maior, r.data[(y * r.width + x) * 4 + 3]);
        amostras++;
      }
    }
    console.log(nome, "amostras:", amostras, "maior alfa no eixo:", maior);
  }
  await b.close();
})();

