// Monta a prancha de revisão com os PNGs gerados. Uso: node prancha-icones.js <assets> <saida> <dir e2e>
const fs = require("fs");
const path = require("path");
const [assets, saida, e2e] = process.argv.slice(2);
const { chromium } = require(require.resolve("@playwright/test", { paths: [e2e] }));
const url = (f) => `data:image/png;base64,${fs.readFileSync(path.join(assets, f)).toString("base64")}`;
const M = "#0B2A55";
const legenda = (t) => `<div style="font:12px sans-serif;color:#556070;margin-top:6px;text-align:center">${t}</div>`;
const bloco = (conteudo, t) => `<div style="display:flex;flex-direction:column;align-items:center">${conteudo}${legenda(t)}</div>`;
const titulo = (t) => `<h2 style="font:700 15px sans-serif;margin:22px 0 10px;color:#0B1B33">${t}</h2>`;
const linha = (c) => `<div style="display:flex;gap:26px;align-items:flex-end;flex-wrap:wrap">${c}</div>`;
const adaptativo = (raio, t) =>
  bloco(
    `<div style="width:180px;height:180px;border-radius:${raio};background:${M};overflow:hidden"><img src="${url("android-icon-foreground.png")}" style="width:180px;height:180px"></div>`,
    t,
  );
const splash = (bg, t) =>
  bloco(
    `<div style="width:195px;height:422px;background:${bg};border:1px solid #C9D0DB;border-radius:18px;display:flex;align-items:center;justify-content:center"><img src="${url("splash-icon.png")}" style="width:100px;height:100px"></div>`,
    t,
  );
const aba = (bg, cor) =>
  `<div style="display:flex;align-items:center;gap:8px;background:${bg};padding:8px 14px;border-radius:8px 8px 0 0;font:12px sans-serif;color:${cor}"><img src="${url("favicon.png")}" style="width:16px;height:16px">Maxx</div>`;
const html = `<body style="margin:0;padding:8px 24px 24px;background:#fff">
${titulo("Ícone (iOS e geral), logo em ouro sobre marinho")}
${linha(
  bloco(`<img src="${url("icon.png")}" style="width:180px;height:180px;border-radius:40px">`, "180 px, com a máscara do iOS") +
    bloco(`<img src="${url("icon.png")}" style="width:60px;height:60px;border-radius:13px">`, "60 px") +
