${titulo("Splash, logo em ouro sobre o bg de cada tema (largura do logo: 180 no aparelho, aqui a 50%)")}
${linha(splash("#FFFFFF", "claro, #FFFFFF") + splash("#06142A", "escuro, #06142A"))}
${titulo("Favicon, recorte do XX")}
${linha(
  bloco(`<img src="${url("favicon.png")}" style="width:128px;height:128px;image-rendering:pixelated">`, "64 px, ampliado 2x") +
    bloco(`<img src="${url("favicon.png")}" style="width:64px;height:64px">`, "64 px") +
    bloco(`<img src="${url("favicon.png")}" style="width:32px;height:32px">`, "32 px") +
    bloco(`<img src="${url("favicon.png")}" style="width:16px;height:16px">`, "16 px") +
    bloco(aba("#DEE1E6", "#202124"), "aba, navegador claro") +
    bloco(aba("#202124", "#E8EAED"), "aba, navegador escuro"),
)}
</body>`;
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 860, height: 1200 }, deviceScaleFactor: 1.5 });
  await p.setContent(html);
  await p.waitForTimeout(400);
  await p.screenshot({ path: saida, fullPage: true });
  await b.close();
})();

