// Gera ícone, adaptativo, splash e favicon do app a partir de design/assets/maxx-ouro.svg.
// Rode da raiz, com o npm ci feito: node design/icones/gerar.js
// Trocar o SVG e rodar de novo basta: nenhum código depende do desenho.
const fs = require("node:fs");
const path = require("node:path");

const raiz = path.resolve(__dirname, "../..");
const { chromium } = require(
  require.resolve("@playwright/test", { paths: [path.join(raiz, "e2e")] }),
);
const tokens = require(path.join(raiz, "design/tokens.json"));

const MARINHO = tokens.cores.claro.hero;
const saida = path.join(raiz, "apps/mobile/assets");
const svg = fs.readFileSync(
  path.join(raiz, "design/assets/maxx-ouro.svg"),
  "utf8",
);
const [, largura, altura] = svg.match(/viewBox="0 0 (\d+) (\d+)"/).map(Number);

// O XX: da borda esquerda do primeiro X até o fim do logo.
const INICIO_DO_XX = 0.5785;

// O logo, ou o recorte do XX, na largura pedida. `cor` troca o ouro, no ícone monocromático.
function logo({ w, cor, xx = false }) {
  let conteudo = svg;
  if (cor)
    conteudo = conteudo.replace(/fill="#[0-9A-Fa-f]{6}"/, `fill="${cor}"`);
  if (xx) {
    const x = Math.round(largura * INICIO_DO_XX);
    conteudo = conteudo.replace(
      /viewBox="[^"]+"/,
      `viewBox="${x} 0 ${largura - x} ${altura}"`,
    );
  }
  const dados = Buffer.from(conteudo).toString("base64");
  return `<img src="data:image/svg+xml;base64,${dados}" style="display:block;width:${w}px">`;
}

const ARQUIVOS = [
  // iOS não aceita transparência: logo em ouro sobre marinho.
  { nome: "icon.png", lado: 1024, fundo: MARINHO, logo: { w: 760 } },
  // Android recorta o adaptativo: o logo fica dentro do círculo seguro, de 66% do lado.
  { nome: "android-icon-foreground.png", lado: 1024, logo: { w: 620 } },
  {
    nome: "android-icon-monochrome.png",
    lado: 1024,
    logo: { w: 620, cor: "#FFFFFF" },
  },
  // Sem fundo: a cor de cada tema vem do app.json.
  { nome: "splash-icon.png", lado: 1024, logo: { w: 920 } },
  // Em aba do navegador, o logo inteiro não se lê: fica só o XX.
  {
    nome: "favicon.png",
    lado: 64,
    fundo: MARINHO,
    raio: 12,
    logo: { w: 52, xx: true },
  },
];

(async () => {
  const navegador = await chromium.launch();
  for (const { nome, lado, fundo, raio = 0, logo: desenho } of ARQUIVOS) {
    const pagina = await navegador.newPage({
      viewport: { width: lado, height: lado },
    });
    await pagina.setContent(`<body style="margin:0;background:transparent">
      <div style="width:${lado}px;height:${lado}px;display:flex;align-items:center;justify-content:center;
        background:${fundo ?? "transparent"};border-radius:${raio}px">${logo(desenho)}</div></body>`);
    await pagina.evaluate(() => document.images[0].decode());
    await pagina.screenshot({
      path: path.join(saida, nome),
      omitBackground: true,
    });
    await pagina.close();
    console.log(nome, fs.statSync(path.join(saida, nome)).size, "bytes");
  }
  await navegador.close();
})();

// Monta a prancha de revisão com os PNGs gerados. Uso: node prancha-icones.js <assets> <saida> <dir e2e>
const fs = require("fs");
const path = require("path");
const [assets, saida, e2e] = process.argv.slice(2);
const { chromium } = require(require.resolve("@playwright/test", { paths: [e2e] }));
const url = (f) => `data:image/png;base64,${fs.readFileSync(path.join(assets, f)).toString("base64")}`;
const M = "#0B2A55";
const legenda = (t) => `<div style="font:12px sans-serif;color:#556070;margin-top:6px;text-align:center">${t}</div>`;
const bloco = (conteudo, t) => `<div style="display:flex;flex-direction:column;align-items:center">${conteudo}${legenda(t)}</div>`;
const titulo = (t) => `<h2 style="font:700 15px sans-serif;margin:22px 0 10px;color:#0B1B33">${t}</h2>`;
const linha = (c) => `<div style="display:flex;gap:26px;align-items:flex-end;flex-wrap:wrap">${c}</div>`;
const adaptativo = (raio, t) =>
  bloco(
    `<div style="width:180px;height:180px;border-radius:${raio};background:${M};overflow:hidden"><img src="${url("android-icon-foreground.png")}" style="width:180px;height:180px"></div>`,
    t,
  );
const splash = (bg, t) =>
  bloco(
    `<div style="width:195px;height:422px;background:${bg};border:1px solid #C9D0DB;border-radius:18px;display:flex;align-items:center;justify-content:center"><img src="${url("splash-icon.png")}" style="width:100px;height:100px"></div>`,
    t,
  );
const aba = (bg, cor) =>
  `<div style="display:flex;align-items:center;gap:8px;background:${bg};padding:8px 14px;border-radius:8px 8px 0 0;font:12px sans-serif;color:${cor}"><img src="${url("favicon.png")}" style="width:16px;height:16px">Maxx</div>`;
const html = `<body style="margin:0;padding:8px 24px 24px;background:#fff">
${titulo("Ícone (iOS e geral), logo em ouro sobre marinho")}
${linha(
  bloco(`<img src="${url("icon.png")}" style="width:180px;height:180px;border-radius:40px">`, "180 px, com a máscara do iOS") +
    bloco(`<img src="${url("icon.png")}" style="width:60px;height:60px;border-radius:13px">`, "60 px") +
    bloco(`<img src="${url("icon.png")}" style="width:180px;height:180px;border:1px solid #DDE2EA">`, "arquivo sem máscara"),
)}
${titulo("Adaptativo do Android, sobre #0B2A55, nas máscaras mais comuns")}
${linha(
  adaptativo("50%", "círculo") +
    adaptativo("28%", "squircle") +
    bloco(
      `<div style="width:180px;height:180px;border-radius:50%;background:#2B3A52;overflow:hidden"><img src="${url("android-icon-monochrome.png")}" style="width:180px;height:180px"></div>`,
      "monocromático (Android 13+)",
    ),
)}
${titulo("Splash, logo em ouro sobre o bg de cada tema (largura do logo: 180 no aparelho, aqui a 50%)")}
${linha(splash("#FFFFFF", "claro, #FFFFFF") + splash("#06142A", "escuro, #06142A"))}
${titulo("Favicon, recorte do XX")}
${linha(
  bloco(`<img src="${url("favicon.png")}" style="width:128px;height:128px;image-rendering:pixelated">`, "64 px, ampliado 2x") +
    bloco(`<img src="${url("favicon.png")}" style="width:64px;height:64px">`, "64 px") +
    bloco(`<img src="${url("favicon.png")}" style="width:32px;height:32px">`, "32 px") +
    bloco(`<img src="${url("favicon.png")}" style="width:16px;height:16px">`, "16 px") +
    bloco(aba("#DEE1E6", "#202124"), "aba, navegador claro") +
    bloco(aba("#202124", "#E8EAED"), "aba, navegador escuro"),
)}
</body>`;
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 860, height: 1200 }, deviceScaleFactor: 1.5 });
  await p.setContent(html);
  await p.waitForTimeout(400);
  await p.screenshot({ path: saida, fullPage: true });
  await b.close();
})();

// Confere se os cortes do XX ficam abertos de ponta a ponta: rasteriza o SVG a 8x e percorre cada
// eixo, marcando o maior alfa encontrado. Uso: node continuidade.js <svg> <dir e2e>
const fs = require("fs");
const { chromium } = require(require.resolve("@playwright/test", { paths: [process.argv[3]] }));
const { PNG } = require(require.resolve("pngjs", { paths: [__dirname] }));
const CORTES = {
  "corte de cima": [[283.5, 2.5], [277.5, 9.5], [272.5, 14.5], [267.5, 19.5], [264.5, 22.5]],
  "corte entre os X": [[285.5, 14.5], [281.5, 18.5], [275.5, 24.5], [270.5, 29.5], [268.5, 31.5]],
};
(async () => {
  const F = 8;
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 338 * F, height: 89 * F } });
  const src = "data:image/svg+xml;base64," + fs.readFileSync(process.argv[2]).toString("base64");
  await p.setContent(`<body style="margin:0;background:transparent"><img src="${src}" style="display:block;width:${338 * F}px;height:${89 * F}px"></body>`);
  await p.waitForTimeout(200);
  const r = PNG.sync.read(await p.screenshot({ omitBackground: true }));
  for (const [nome, pontos] of Object.entries(CORTES)) {
    let maior = 0;
    let amostras = 0;
    for (let i = 0; i < pontos.length - 1; i++) {
      const [ax, ay] = pontos[i];
      const [bx, by] = pontos[i + 1];
      for (let t = 0; t <= 1; t += 0.01) {
        const x = Math.round((ax + (bx - ax) * t) * F);
        const y = Math.round((ay + (by - ay) * t) * F);
        maior = Math.max(maior, r.data[(y * r.width + x) * 4 + 3]);
        amostras++;
      }
    }
    console.log(nome, "amostras:", amostras, "maior alfa no eixo:", maior);
  }
  await b.close();
})();

